{
  "capabilities": [
    {
      "name": "User Registration and Authentication",
      "description": "Users can register with username/password, log in, maintain a session in the browser, and log out. Access is denied on invalid credentials or role mismatch.",
      "evidence": ["RF-01", "RF-02", "RF-04", "RF-05", "RF-07", "UserController"]
    },
    {
      "name": "Role-Based Access Control",
      "description": "The system distinguishes regular users and administrators, restricting the resource-management area to administrators.",
      "evidence": ["RF-03", "RF-06", "RNF-45", "RNF-46", "RNF-55"]
    },
    {
      "name": "Movie Catalog Browsing",
      "description": "Home page lists available movies with title, poster, and rating; listing is paginated and supports opening a details page.",
      "evidence": ["RF-08", "RF-09", "RF-10", "RF-11", "RF-12", "RNF-40", "MovieController"]
    },
    {
      "name": "Movie Details Lookup",
      "description": "Provides a per-movie details page showing full metadata and complete cast, with error handling for nonexistent movies.",
      "evidence": ["RF-13", "RF-14", "RF-15", "RF-16"]
    },
    {
      "name": "Category-Based Content Discovery",
      "description": "Users can browse by category, view all categories, filter movies by a selected category, and return to the full catalog.",
      "evidence": ["RF-17", "RF-18", "RF-19", "RF-21", "TypeController"]
    },
    {
      "name": "Movie Playback and File Delivery",
      "description": "Playback can be started from the details page and a download link is provided; the system ensures the video file is available in the delivery area, falling back to a configured local repository.",
      "evidence": ["RF-22", "RF-23", "RF-24", "RF-25", "RNF-50", "RNF-51"]
    },
    {
      "name": "Catalog Administration",
      "description": "Administrators register, delete (single and batch), and manage movies, with duplicate-title prevention and confirmation before batch deletion.",
      "evidence": ["RF-26", "RF-27", "RF-28", "RF-30", "RF-31", "RF-32", "RF-33"]
    },
    {
      "name": "Movie Video Upload",
      "description": "Administrators upload movie video files (up to 2 GB, MP4 standard) as a step related to but independent from movie registration.",
      "evidence": ["RF-29", "RNF-48", "RNF-49", "RNF-57", "MovieUploadController"]
    },
    {
      "name": "Persistent Structured Storage",
      "description": "User, movie, and category data are persistently stored in a structured database supporting catalog relationships.",
      "evidence": ["RNF-42", "RNF-54", "javax.persistence", "io.innofang.jokul.repositories"]
    },
    {
      "name": "Consistent Response and Error Handling",
      "description": "Operations return a consistent response format (status, message, data) with controlled error messages and clear success/warning/failure feedback.",
      "evidence": ["RF-16", "RNF-39", "RNF-41", "RNF-44", "io.innofang.jokul.handle", "io.innofang.jokul.exception"]
    }
  ],
  "domain_entities": [
    "User",
    "UserRole (regular user, administrator)",
    "Movie",
    "Category",
    "CastMember (cast)",
    "MovieVideoFile"
  ],
  "business_rules": [
    "Movie title is the unique identifier for catalog registration; duplicate titles are prevented (RF-28, RF-35).",
    "Usernames must be unique; duplicate user registration is prevented (RF-34, RNF-43).",
    "A movie can belong to multiple categories (RF-20, RNF-56).",
    "Catalog-management functions are restricted to the administrator role (RF-06, RNF-46).",
    "Access is denied when the user does not exist, the password is incorrect, or the role does not match registration (RF-04).",
    "Uploading the video file and registering the movie are related but independent steps (RNF-57).",
    "Automatic playback depends on an MP4 file corresponding to the registered title (RF-36, RNF-58, RNF-62).",
    "The source movie filename must follow the environment-configured pattern for automatic loading (RNF-59).",
    "If a video file is not in the delivery area, the system attempts to obtain it from the configured local repository (RF-25).",
    "Deletion of nonexistent movies is prevented; batch deletion informs the admin of selected movies first (RF-32, RF-33).",
    "The catalog is displayed in pages of up to 12 movies (RNF-40).",
    "Standard video format is MP4; uploads supported up to 2 GB per file (RNF-48, RNF-49)."
  ],
  "unresolved_questions": [
    "Backend enforcement of administrator-only resource management is noted as not fully validated (RNF-60); actual authorization coverage is uncertain.",
    "The evidence does not clarify whether cast is modeled as a distinct entity or as a plain attribute of Movie.",
    "Rating semantics (e.g., age rating vs. review score) are not defined in the evidence.",
    "No entity for access/login records is confirmed despite mention of 'access records' in RNF-43.",
    "The relationship and lifecycle between uploaded video files, the delivery area, and the local repository are only partially specified."
  ]
}

