      "communicates_with": [
        "User and Access Service",
        "Media Delivery Service"
      ]
    },
    {
      "microservice_name": "Media Delivery Service",
      "responsibility": "Manages movie video uploads (up to 2 GB MP4), ensures video availability in the delivery area with fallback to the configured local repository, provides playback start and download links based on filename-pattern conventions. Backed by MovieUploadController and file utilities/properties.",
      "communicates_with": [
        "Catalog Service",
        "User and Access Service"
      ]
    }
  ]
}

